style.css:
@-moz-document domain("youtube.com") {
/* 1. Main Background Image Setup */
    body, 
    ytd-app, 
    #page-manager, 
    ytd-browse, 
    ytd-watch-flexy {
        background: url("https://www.newsweek.com/sydney-sweeney-male-gaze-saturday-night-live-1875971") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* 2. Make YouTube Panels Transparent */
    ytd-masthead,
    #masthead-container,
    #background.ytd-masthead,
    ytd-mini-guide-renderer,
    ytd-guide-renderer,
    #guide-content,
    ytd-browse[page-subtype="home"],
    #contentContainer,
    #columns,
    ytd-rich-grid-renderer,
    #page-manager ytd-browse,
    ytd-playlist-sidebar-renderer,
    #contents.ytd-item-section-renderer,
    ytd-engagement-panel-section-list-renderer {
        background: rgba(0, 0, 0, 0.4) !important; /* Semi-transparent black */
    }

    /* 3. Make Video and Channel Cards Transparent */
    ytd-rich-item-renderer,
    ytd-video-renderer,
    ytd-compact-video-renderer,
    ytd-grid-video-renderer,
    #meta.ytd-watch-flexy,
    #ticket-shelf,
    ytd-merch-shelf-renderer,
    ytd-structured-description-content-renderer {
        background: rgba(20, 20, 20, 0.6) !important;
        border-radius: 12px;
        padding: 10px;
    }

    /* 4. Text Contrast Adjustments */
    #video-title, 
    #title, 
    span, 
    #channel-name {
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.8) !important;
    }
}
